"use client";

import { useEffect, useState } from "react";
import { apiGet } from "@/lib/api-client";
import { useAppStore } from "@/store/app-store";
import { PageHeader } from "@/components/app/page-header";
import { StatusBadge } from "@/components/app/status-badge";
import { EmptyState, LoadingState, ErrorState } from "@/components/app/empty-state";
import { Card, CardContent } from "@/components/ui/card";
import { Input } from "@/components/ui/input";
import { ClipboardCheck, Search, MapPin, Calendar, Heart, ChevronRight } from "lucide-react";
import { formatDate } from "@/lib/constants";

export function InspectionList() {
  const { navigate } = useAppStore();
  const [requests, setRequests] = useState<any[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState("");
  const [search, setSearch] = useState("");

  useEffect(() => {
    (async () => {
      try { const d = await apiGet("/transport-requests"); setRequests(d.requests); }
      catch (e: any) { setError(e.message); }
      finally { setLoading(false); }
    })();
  }, []);

  if (loading) return <LoadingState />;
  if (error) return <ErrorState message={error} />;

  const filtered = requests.filter((r) => !search || (r.competitionName || "").toLowerCase().includes(search.toLowerCase()));

  return (
    <div className="space-y-6">
      <PageHeader title="Hồ sơ thẩm định" description="Danh sách đơn cần thẩm định hồ sơ pháp lý & kiểm dịch" icon={<ClipboardCheck className="h-5 w-5" />}
        actions={<div className="relative w-full sm:w-64"><Search className="absolute left-3 top-1/2 h-4 w-4 -translate-y-1/2 text-muted-foreground" /><Input value={search} onChange={(e) => setSearch(e.target.value)} placeholder="Tìm đơn..." className="pl-9" /></div>}
      />
      {filtered.length === 0 ? (
        <EmptyState icon={<ClipboardCheck className="h-6 w-6" />} title="Không có đơn cần thẩm định" />
      ) : (
        <div className="space-y-3">
          {filtered.map((r) => (
            <button key={r.requestId} onClick={() => navigate("inspection-detail", { id: r.requestId })} className="flex w-full items-center gap-4 rounded-xl border border-border bg-card p-4 text-left transition-all hover:border-primary/40 hover:shadow-md">
              <div className="flex h-12 w-12 shrink-0 items-center justify-center rounded-xl bg-primary/10 text-primary"><ClipboardCheck className="h-6 w-6" /></div>
              <div className="min-w-0 flex-1">
                <p className="truncate text-sm font-semibold">{r.competitionName || `Đơn #${r.requestId.slice(-8)}`}</p>
                <div className="mt-1 flex flex-wrap items-center gap-x-4 gap-y-1 text-xs text-muted-foreground">
                  <span>{r.customer?.name}</span>
                  <span className="flex items-center gap-1"><MapPin className="h-3 w-3" />{r.origin?.name} → {r.destination?.name}</span>
                  <span className="flex items-center gap-1"><Calendar className="h-3 w-3" />{formatDate(r.scheduledDepartureDate)}</span>
                  <span className="flex items-center gap-1"><Heart className="h-3 w-3" />{r.horses?.length || 0} ngựa</span>
                </div>
              </div>
              <StatusBadge status={r.status} />
              <ChevronRight className="h-4 w-4 text-muted-foreground" />
            </button>
          ))}
        </div>
      )}
    </div>
  );
}
