"use client";

import { useEffect, useState } from "react";
import { apiGet } from "@/lib/api-client";
import { useAppStore } from "@/store/app-store";
import { PageHeader } from "@/components/app/page-header";
import { StatCard } from "@/components/app/stat-card";
import { StatusBadge } from "@/components/app/status-badge";
import { EmptyState, LoadingState, ErrorState } from "@/components/app/empty-state";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { ClipboardCheck, FileText, Clock, Bell, MapPin, ChevronRight, ShieldCheck } from "lucide-react";
import { formatDate } from "@/lib/constants";
import { RecentActivity } from "@/components/app/recent-activity";

export function SpecialistDashboard() {
  const { navigate } = useAppStore();
  const [data, setData] = useState<any>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState("");

  useEffect(() => {
    (async () => {
      try { setData(await apiGet("/dashboard")); }
      catch (e: any) { setError(e.message); }
      finally { setLoading(false); }
    })();
  }, []);

  if (loading) return <LoadingState />;
  if (error) return <ErrorState message={error} />;

  const { stats, recent, notifications } = data;

  return (
    <div className="space-y-6">
      <PageHeader title="Tổng quan Chuyên viên" description="Thẩm định hồ sơ pháp lý, kiểm dịch và thông quan" icon={<ShieldCheck className="h-5 w-5" />} />

      <div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-4">
        <StatCard label="Chờ thẩm định" value={stats.pendingReview} icon={<ClipboardCheck className="h-6 w-6" />} tone="warning" delay={0} tooltip="Số đơn đang chờ bạn thẩm định hồ sơ pháp lý + kiểm dịch." />
        <StatCard label="Kiểm dịch đang xử lý" value={stats.activeInspections} icon={<ShieldCheck className="h-6 w-6" />} tone="info" delay={0.05} tooltip="Số hồ sơ kiểm dịch đang ở trạng thái Chờ kiểm tra / Đang kiểm tra / Cần bổ sung." />
        <StatCard label="Tài liệu chờ duyệt" value={stats.docsPending} icon={<FileText className="h-6 w-6" />} tone="default" delay={0.1} tooltip="Số tài liệu đã nộp hoặc đang kiểm tra — cần bạn xem xét duyệt hoặc yêu cầu bổ sung." />
        <StatCard label="Tổng đơn đang xử lý" value={stats.total} icon={<Clock className="h-6 w-6" />} tone="success" delay={0.15} tooltip="Tổng số đơn đang ở các trạng thái cần bạn xử lý (Đã gửi, Đang thẩm định, Trả lại bổ sung)." />
      </div>

      <div className="grid gap-6 lg:grid-cols-3">
        <Card className="lg:col-span-2">
          <CardHeader className="flex flex-row items-center justify-between">
            <CardTitle className="text-base">Đơn cần thẩm định</CardTitle>
            <Button variant="ghost" size="sm" onClick={() => navigate("inspections")} className="gap-1 text-muted-foreground">Xem tất cả <ChevronRight className="h-4 w-4" /></Button>
          </CardHeader>
          <CardContent>
            {recent.length === 0 ? (
              <EmptyState icon={<ClipboardCheck className="h-6 w-6" />} title="Không có đơn chờ thẩm định" description="Các đơn mới gửi sẽ xuất hiện tại đây." />
            ) : (
              <div className="space-y-2">
                {recent.map((r: any) => (
                  <button key={r.requestId} onClick={() => navigate("inspection-detail", { id: r.requestId })} className="flex w-full items-center gap-4 rounded-lg border border-border bg-card p-3 text-left transition-all hover:border-primary/40 hover:shadow-sm">
                    <div className="flex h-10 w-10 shrink-0 items-center justify-center rounded-lg bg-primary/10 text-primary"><FileText className="h-5 w-5" /></div>
                    <div className="min-w-0 flex-1">
                      <p className="truncate text-sm font-semibold">{r.competitionName || `Đơn #${r.requestId.slice(-8)}`}</p>
                      <div className="mt-0.5 flex items-center gap-3 text-xs text-muted-foreground">
                        <span>{r.customer?.name}</span>
                        <span className="flex items-center gap-1"><MapPin className="h-3 w-3" />{r.origin?.name} → {r.destination?.name}</span>
                      </div>
                    </div>
                    <StatusBadge status={r.status} />
                  </button>
                ))}
              </div>
            )}
          </CardContent>
        </Card>

        <Card>
          <CardHeader className="flex flex-row items-center justify-between"><CardTitle className="text-base">Thông báo</CardTitle><Bell className="h-4 w-4 text-muted-foreground" /></CardHeader>
          <CardContent>
            {notifications.length === 0 ? <p className="py-8 text-center text-sm text-muted-foreground">Không có thông báo</p> : (
              <div className="space-y-3">
                {notifications.map((n: any) => (
                  <div key={n.notificationId} className="rounded-lg border border-border p-3">
                    <p className="text-sm font-medium leading-tight">{n.title}</p>
                    <p className="mt-1 text-xs text-muted-foreground line-clamp-2">{n.message}</p>
                    <p className="mt-1 text-[10px] text-muted-foreground">{formatDate(n.createdAt)}</p>
                  </div>
                ))}
              </div>
            )}
          </CardContent>
        </Card>
      </div>

      {/* Recent activity timeline */}
      <RecentActivity />
    </div>
  );
}
