"use client";

import { useEffect, useState } from "react";
import { apiGet } from "@/lib/api-client";
import { useAppStore } from "@/store/app-store";
import { PageHeader } from "@/components/app/page-header";
import { StatCard } from "@/components/app/stat-card";
import { StatusBadge } from "@/components/app/status-badge";
import { EmptyState, LoadingState, ErrorState } from "@/components/app/empty-state";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Bell, MapPin, Truck, ClipboardList, ChevronRight, Heart, Navigation, Flag, Clock, Activity, Plus } from "lucide-react";
import { formatDate, formatDateTime } from "@/lib/constants";
import { RecentActivity } from "@/components/app/recent-activity";

export function DriverDashboard() {
  const { navigate } = useAppStore();
  const [data, setData] = useState<any>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState("");

  useEffect(() => {
    (async () => {
      try { setData(await apiGet("/dashboard")); }
      catch (e: any) { setError(e.message); }
      finally { setLoading(false); }
    })();
  }, []);

  if (loading) return <LoadingState />;
  if (error) return <ErrorState message={error} />;

  const { stats, recent, notifications } = data;

  return (
    <div className="space-y-6">
      <PageHeader title="Tổng quan Tài xế / Đi kèm" description="Chuyến được phân công và cập nhật hành trình" icon={<Truck className="h-5 w-5" />} />

      <div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-4">
        <StatCard label="Tổng chuyến được giao" value={stats.totalAssignments} icon={<ClipboardList className="h-6 w-6" />} tone="default" delay={0} tooltip="Tổng số chuyến bạn đã được phân công (làm tài xế hoặc nhân viên đi kèm) trong hệ thống." />
        <StatCard label="Chuyến đang chạy" value={stats.active} icon={<Truck className="h-6 w-6" />} tone="info" hint="Sẵn sàng / Đang thực hiện" delay={0.05} tooltip="Số chuyến đang ở trạng thái Sẵn sàng khởi hành hoặc Đang thực hiện — cần bạn cập nhật mốc, nhật ký sức khỏe, báo sự cố." />
      </div>

      {/* Today's active trip - prominent card */}
      {(() => {
        const activeTrip = recent.find((p: any) => ["Đang thực hiện", "Sẵn sàng"].includes(p.status));
        if (!activeTrip) return null;
        const completedStops = activeTrip.stops?.filter((s: any) => s.status === "Đã khởi hành").length || 0;
        const totalStops = activeTrip.stops?.length || 0;
        return (
          <Card className="gradient-accent-border border-primary/30 bg-card overflow-hidden">
            <div className="h-1.5 bg-gradient-to-r from-primary via-[var(--copper)] to-[var(--success)]" />
            <CardContent className="p-5">
              <div className="flex items-center justify-between gap-3 mb-4">
                <div className="flex items-center gap-2">
                  <span className="flex h-8 w-8 items-center justify-center rounded-lg bg-[var(--success)]/15 text-[var(--success)]"><Truck className="h-4 w-4 animate-pulse-soft" /></span>
                  <div>
                    <p className="text-xs font-semibold uppercase tracking-wider text-[var(--success-fg)]">Chuyến đang hoạt động</p>
                    <p className="text-[10px] text-muted-foreground">Cập nhật tiến độ nhanh</p>
                  </div>
                </div>
                <StatusBadge status={activeTrip.status} />
              </div>

              <button onClick={() => navigate("trip-detail", { id: activeTrip.planId })} className="block w-full text-left">
                <h3 className="text-lg font-bold tracking-tight hover:text-primary transition-colors">{activeTrip.request?.competitionName || `Chuyến #${activeTrip.planId.slice(-8)}`}</h3>
                <div className="mt-1 flex flex-wrap items-center gap-x-4 gap-y-1 text-xs text-muted-foreground">
                  <span className="flex items-center gap-1"><Navigation className="h-3 w-3" />{activeTrip.request?.origin?.name}</span>
                  <span className="text-muted-foreground/40">→</span>
                  <span className="flex items-center gap-1"><Flag className="h-3 w-3" />{activeTrip.request?.destination?.name}</span>
                  <span className="flex items-center gap-1"><Clock className="h-3 w-3" />{formatDateTime(activeTrip.departureTime)}</span>
                  <span className="flex items-center gap-1"><Heart className="h-3 w-3" />{activeTrip.request?.horses?.length || 0} ngựa</span>
                </div>
                {totalStops > 0 && (
                  <div className="mt-3">
                    <div className="flex justify-between text-[10px] text-muted-foreground mb-1">
                      <span>Tiến độ chặng</span>
                      <span>{completedStops}/{totalStops}</span>
                    </div>
                    <div className="h-1.5 overflow-hidden rounded-full bg-muted">
                      <div className="h-full rounded-full bg-gradient-to-r from-primary to-[var(--copper)]" style={{ width: `${(completedStops / totalStops) * 100}%` }} />
                    </div>
                  </div>
                )}
              </button>

              {/* Quick action buttons */}
              <div className="mt-4 grid grid-cols-2 gap-2 sm:grid-cols-4">
                <button onClick={() => navigate("trip-detail", { id: activeTrip.planId })} className="flex flex-col items-center gap-1 rounded-lg border border-border bg-muted/30 p-2.5 text-center transition-all hover:border-primary/40 hover:bg-primary/5">
                  <Plus className="h-4 w-4 text-primary" />
                  <span className="text-[10px] font-medium">Cập nhật mốc</span>
                </button>
                <button onClick={() => { navigate("trip-detail", { id: activeTrip.planId }); setTimeout(() => { const el = document.querySelector('[role="tab"][data-state]'); }, 100); }} className="flex flex-col items-center gap-1 rounded-lg border border-border bg-muted/30 p-2.5 text-center transition-all hover:border-primary/40 hover:bg-primary/5">
                  <Activity className="h-4 w-4 text-[var(--success)]" />
                  <span className="text-[10px] font-medium">Sức khỏe</span>
                </button>
                <button onClick={() => navigate("trip-detail", { id: activeTrip.planId })} className="flex flex-col items-center gap-1 rounded-lg border border-border bg-muted/30 p-2.5 text-center transition-all hover:border-[var(--danger)]/40 hover:bg-[var(--danger-bg)]/30">
                  <Flag className="h-4 w-4 text-[var(--danger)]" />
                  <span className="text-[10px] font-medium">Báo sự cố</span>
                </button>
                <button onClick={() => navigate("trip-detail", { id: activeTrip.planId })} className="flex flex-col items-center gap-1 rounded-lg border border-border bg-muted/30 p-2.5 text-center transition-all hover:border-primary/40 hover:bg-primary/5">
                  <ClipboardList className="h-4 w-4 text-[var(--copper)]" />
                  <span className="text-[10px] font-medium">Chi tiết</span>
                </button>
              </div>
            </CardContent>
          </Card>
        );
      })()}

      <div className="grid gap-6 lg:grid-cols-3">
        <Card className="lg:col-span-2">
          <CardHeader className="flex flex-row items-center justify-between">
            <CardTitle className="text-base">Chuyến được giao</CardTitle>
            <button onClick={() => navigate("trips")} className="flex items-center gap-1 text-xs text-muted-foreground hover:text-foreground">Xem tất cả <ChevronRight className="h-3 w-3" /></button>
          </CardHeader>
          <CardContent>
            {recent.length === 0 ? (
              <EmptyState icon={<Truck className="h-6 w-6" />} title="Chưa có chuyến được giao" description="Khi được phân công, chuyến sẽ hiển thị tại đây." />
            ) : (
              <div className="space-y-2">
                {recent.map((p: any) => (
                  <button key={p.planId} onClick={() => navigate("trip-detail", { id: p.planId })} className="flex w-full items-center gap-4 rounded-lg border border-border bg-card p-3 text-left transition-all hover:border-primary/40 hover:shadow-sm">
                    <div className="flex h-10 w-10 shrink-0 items-center justify-center rounded-lg bg-primary/10 text-primary"><Truck className="h-5 w-5" /></div>
                    <div className="min-w-0 flex-1">
                      <p className="truncate text-sm font-semibold">{p.request?.competitionName || `Chuyến #${p.planId.slice(-8)}`}</p>
                      <div className="mt-0.5 flex flex-wrap items-center gap-x-3 gap-y-0.5 text-xs text-muted-foreground">
                        <span className="flex items-center gap-1"><MapPin className="h-3 w-3" />{p.request?.origin?.name} → {p.request?.destination?.name}</span>
                        <span className="flex items-center gap-1"><Heart className="h-3 w-3" />{p.request?.horses?.length || 0} ngựa</span>
                        <span>{formatDateTime(p.departureTime)}</span>
                      </div>
                    </div>
                    <StatusBadge status={p.status} />
                  </button>
                ))}
              </div>
            )}
          </CardContent>
        </Card>

        <Card>
          <CardHeader className="flex flex-row items-center justify-between"><CardTitle className="text-base">Thông báo</CardTitle><Bell className="h-4 w-4 text-muted-foreground" /></CardHeader>
          <CardContent>
            {notifications.length === 0 ? <p className="py-8 text-center text-sm text-muted-foreground">Không có thông báo</p> : (
              <div className="space-y-3">
                {notifications.map((n: any) => (
                  <div key={n.notificationId} className={`rounded-lg border p-3 ${n.type === "INCIDENT_SOS" ? "border-[var(--danger)]/30 bg-[var(--danger-bg)]" : "border-border"}`}>
                    <p className="text-sm font-medium leading-tight">{n.title}</p>
                    <p className="mt-1 text-xs text-muted-foreground line-clamp-2">{n.message}</p>
                    <p className="mt-1 text-[10px] text-muted-foreground">{formatDate(n.createdAt)}</p>
                  </div>
                ))}
              </div>
            )}
          </CardContent>
        </Card>
      </div>

      {/* Recent activity timeline */}
      <RecentActivity />
    </div>
  );
}
